// Canvas platformer. Question callbacks are supplied by the study app.
window.VoyageGame=(()=>{let active=null;const W=900,H=390,GROUND=315;
function start({questions,onGrade,onFinish,escape,normalize}){
  if(active)active.stop();
  const host=document.querySelector('#card');host.innerHTML=`<div class="game-wrap"><div class="game-hud"><span id="game-level">歴史の航路 · 1 / ${questions.length}</span><span id="game-lives">♥ ♥ ♥</span><span id="game-stars">✦ 0</span></div><div class="game-frame"><canvas width="${W}" height="${H}" aria-label="歴史の横スクロールアクションゲーム"></canvas><div id="game-overlay"></div></div><p class="game-help">← → または A / D で移動、Space / ↑ / W でジャンプ。旗まで進むと歴史の問題が出ます。スマホは下のボタンで操作できます。</p><div class="game-touch"><div><button data-control="left" aria-label="左へ">←</button><button data-control="right" aria-label="右へ">→</button></div><button class="jump" data-control="jump" aria-label="ジャンプ">ジャンプ ↑</button></div></div>`;
  const c=host.querySelector('canvas'),ctx=c.getContext('2d'),overlay=host.querySelector('#game-overlay');let keys={left:false,right:false,jump:false},p={x:45,y:GROUND-34,vx:0,vy:0,w:30,h:34,onGround:false,invuln:0},lives=3,stars=0,gate=0,camera=0,paused=false,raf=0,ended=false;const gateX=i=>310+i*350,finishX=gateX(questions.length-1)+240,worldW=finishX+300;
  const platforms=questions.map((_,i)=>({x:gateX(i)+100,y:240-(i%2)*38,w:116,h:15}));const hazards=questions.map((_,i)=>({x:gateX(i)+165,y:GROUND-18,w:33,h:18}));const coins=questions.map((_,i)=>({x:gateX(i)+125,y:205-(i%2)*38,taken:false}));
  function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#b9e2ed';ctx.fillRect(0,0,W,H);let cam=camera;
    // Parallax hills and clouds.
    ctx.fillStyle='#f7fcfa';for(let i=0;i<12;i++){let x=i*370-(cam*.25)%370;ctx.beginPath();ctx.ellipse(x+90,57+(i%3)*24,51,14,0,0,7);ctx.fill()}
    ctx.fillStyle='#8abcae';for(let i=0;i<17;i++){let x=i*270-(cam*.5)%270;ctx.beginPath();ctx.moveTo(x-160,GROUND);ctx.lineTo(x+55,166+(i%3)*24);ctx.lineTo(x+240,GROUND);ctx.fill()}
    ctx.fillStyle='#e5e2c2';ctx.fillRect(0,GROUND,W,H-GROUND);ctx.fillStyle='#5d9a75';ctx.fillRect(0,GROUND,W,10);for(let i=0;i<30;i++){let x=i*64-cam%64;ctx.fillStyle='#b2a783';ctx.fillRect(x,GROUND+32+(i%3)*8,12,3)}
    platforms.forEach(o=>{let x=o.x-cam;if(x<-o.w||x>W)return;ctx.fillStyle='#685375';ctx.fillRect(x,o.y,o.w,o.h);ctx.fillStyle='#96c36b';ctx.fillRect(x,o.y,o.w,5)});
    hazards.forEach(o=>{let x=o.x-cam;if(x<-40||x>W)return;ctx.fillStyle='#d85879';ctx.beginPath();ctx.moveTo(x,GROUND);ctx.lineTo(x+o.w/2,GROUND-o.h);ctx.lineTo(x+o.w,GROUND);ctx.fill()});
    coins.forEach(o=>{if(o.taken)return;let x=o.x-cam;if(x<-20||x>W)return;ctx.fillStyle='#ffd369';ctx.beginPath();ctx.arc(x,o.y,11,0,7);ctx.fill();ctx.fillStyle='#b88143';ctx.font='bold 14px sans-serif';ctx.fillText('✦',x-7,o.y+5)});
    questions.forEach((_,i)=>{let x=gateX(i)-cam;if(x<-30||x>W)return;ctx.fillStyle=i<gate?'#63b89c':'#d85879';ctx.fillRect(x,GROUND-66,5,66);ctx.beginPath();ctx.moveTo(x+5,GROUND-66);ctx.lineTo(x+46,GROUND-56);ctx.lineTo(x+5,GROUND-45);ctx.fill();ctx.fillStyle='#243956';ctx.font='bold 13px sans-serif';ctx.fillText(String(i+1),x+18,GROUND-47)});
    let fx=finishX-cam;if(fx>-80&&fx<W+50){ctx.fillStyle='#30435b';ctx.fillRect(fx,GROUND-105,8,105);ctx.font='51px sans-serif';ctx.fillText('🏁',fx-6,GROUND-59)}
    let px=p.x-cam;if(p.invuln%10<5){ctx.fillStyle='#283c5c';ctx.fillRect(px+6,p.y+10,19,24);ctx.fillStyle='#ffd4a2';ctx.fillRect(px+7,p.y+2,17,16);ctx.fillStyle='#e45980';ctx.fillRect(px+4,p.y,22,7);ctx.fillStyle='#fff';ctx.fillRect(px+19,p.y+11,4,4);ctx.fillStyle='#283c5c';ctx.fillRect(px+8,p.y+32,7,3);ctx.fillRect(px+20,p.y+32,7,3)}
  }
  function hit(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
  function hurt(){if(p.invuln||paused)return;lives--;p.invuln=70;document.querySelector('#game-lives').textContent='♥ '.repeat(lives)+'♡ '.repeat(3-lives);if(lives<=0){lives=3;document.querySelector('#game-lives').textContent='♥ ♥ ♥';}p.x=gate===0?45:gateX(gate-1)+48;p.y=GROUND-p.h;p.vx=p.vy=0;}
  function tick(){if(ended)return;if(!paused){p.vx=(keys.right?3.8:0)-(keys.left?3.8:0);p.x=Math.max(0,Math.min(worldW-p.w,p.x+p.vx));if(keys.jump&&p.onGround){p.vy=-10.8;p.onGround=false}p.vy=Math.min(12,p.vy+.48);let oldBottom=p.y+p.h;p.y+=p.vy;p.onGround=false;if(p.y+p.h>=GROUND){p.y=GROUND-p.h;p.vy=0;p.onGround=true}for(let o of platforms){if(p.vy>=0&&oldBottom<=o.y+5&&hit(p,o)){p.y=o.y-p.h;p.vy=0;p.onGround=true}}if(p.invuln)p.invuln--;for(let o of hazards)if(hit(p,o))hurt();for(let o of coins)if(!o.taken&&Math.abs(p.x+p.w/2-o.x)<22&&Math.abs(p.y+p.h/2-o.y)<27){o.taken=true;stars++;document.querySelector('#game-stars').textContent='✦ '+stars}if(gate<questions.length&&p.x+p.w>=gateX(gate)){p.x=gateX(gate)-p.w;quiz()}else if(gate>=questions.length&&p.x>finishX){ended=true;stop();onFinish({stars,lives})}camera=Math.max(0,Math.min(worldW-W,p.x-210))}draw();raf=requestAnimationFrame(tick)}
  function quiz(){paused=true;keys.left=keys.right=keys.jump=false;let q=questions[gate],choices=[q.answer,...q.distractors].sort(()=>Math.random()-.5),isWrite=false;overlay.innerHTML=`<div class="game-question"><div class="panel"><span class="unit-badge">第${gate+1}の関門 · ${escape(q.unit)}</span><h3>${escape(q.question)}</h3><div class="choices">${choices.map((v,i)=>`<button class="choice" data-value="${escape(v)}"><span>${'ABCD'[i]}</span>${escape(v)}</button>`).join('')}</div><div id="gate-feedback"></div></div></div>`;overlay.querySelectorAll('.choice').forEach(b=>b.onclick=()=>respond(b.dataset.value));
    function respond(value){if(overlay.querySelector('.feedback'))return;let ok=normalize(value)===normalize(q.answer);onGrade(q,ok);overlay.querySelectorAll('.choice').forEach(b=>{b.disabled=true;if(b.dataset.value===q.answer)b.classList.add('correct');else if(b.dataset.value===value)b.classList.add('wrong')});overlay.querySelector('#gate-feedback').innerHTML=`<div class="feedback ${ok?'':'bad'}"><strong>${ok?'正解！':'正解は「'+escape(q.answer)+'」'}</strong><p>${escape(q.explanation)}</p><button class="primary" id="gate-next">${ok?'先へ進む':'覚えて進む'} →</button></div>`;overlay.querySelector('#gate-next').onclick=()=>{gate++;document.querySelector('#game-level').textContent=`歴史の航路 · ${Math.min(gate+1,questions.length)} / ${questions.length}`;document.querySelector('#counter').textContent=`GATE ${gate} / ${questions.length}`;document.querySelector('#progress').style.width=gate/questions.length*100+'%';p.x+=45;p.invuln=35;overlay.innerHTML='';paused=false};}
  }
  function down(e){if(['ArrowLeft','ArrowRight','ArrowUp','Space','KeyA','KeyD','KeyW'].includes(e.code))e.preventDefault();if(e.code==='ArrowLeft'||e.code==='KeyA')keys.left=true;if(e.code==='ArrowRight'||e.code==='KeyD')keys.right=true;if(['ArrowUp','Space','KeyW'].includes(e.code))keys.jump=true}
  function up(e){if(e.code==='ArrowLeft'||e.code==='KeyA')keys.left=false;if(e.code==='ArrowRight'||e.code==='KeyD')keys.right=false;if(['ArrowUp','Space','KeyW'].includes(e.code))keys.jump=false}
  window.addEventListener('keydown',down);window.addEventListener('keyup',up);let buttons=host.querySelectorAll('[data-control]');buttons.forEach(b=>{let k=b.dataset.control;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[k]=true});b.addEventListener('pointerup',e=>{e.preventDefault();keys[k]=false});b.addEventListener('pointercancel',()=>keys[k]=false)});
  function stop(){ended=true;cancelAnimationFrame(raf);window.removeEventListener('keydown',down);window.removeEventListener('keyup',up);active=null}active={stop};raf=requestAnimationFrame(tick);return active;
}return{start,stop:()=>active?.stop()}})();
